const express = require('express');
const { Pool } = require('pg');

const app = express();
const port = process.env.PORT || 8080;

const pool = new Pool({
  host: process.env.PGHOST,
  user: process.env.PGUSER,
  database: process.env.PGDATABASE,
  password: process.env.POSTGRES_PASSWORD,
});

let dbReady = false;

async function initDb() {
  while (!dbReady) {
    try {
      await pool.query(`
        CREATE TABLE IF NOT EXISTS entries (
          id SERIAL PRIMARY KEY,
          name TEXT NOT NULL,
          message TEXT NOT NULL,
          created_at TIMESTAMPTZ NOT NULL DEFAULT now()
        )
      `);
      dbReady = true;
    } catch (err) {
      console.error('waiting for database:', err.message);
      await new Promise((r) => setTimeout(r, 1000));
    }
  }
}

initDb();

app.use(express.urlencoded({ extended: false }));

function escapeHtml(str) {
  return str.replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  }[c]));
}

app.get('/healthz', async (req, res) => {
  if (!dbReady) return res.sendStatus(503);
  try {
    await pool.query('SELECT 1');
    res.sendStatus(200);
  } catch {
    res.sendStatus(503);
  }
});

app.get('/', async (req, res) => {
  let rows = [];
  try {
    const result = await pool.query(
      'SELECT name, message, created_at FROM entries ORDER BY id DESC LIMIT 200'
    );
    rows = result.rows;
  } catch (err) {
    console.error(err);
  }

  const entriesHtml = rows
    .map(
      (r) => `
    <li class="entry">
      <p class="entry-message">${escapeHtml(r.message)}</p>
      <p class="entry-meta">— ${escapeHtml(r.name)} · ${new Date(
        r.created_at
      ).toLocaleString()}</p>
    </li>`
    )
    .join('');

  res.send(`<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Guestbook</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 640px; margin: 40px auto; padding: 0 16px; color: #222; }
  h1 { margin-bottom: 4px; }
  form { display: flex; flex-direction: column; gap: 8px; margin: 24px 0; }
  input, textarea { font: inherit; padding: 8px; border: 1px solid #ccc; border-radius: 4px; }
  button { font: inherit; padding: 8px 16px; border: none; border-radius: 4px; background: #2563eb; color: white; cursor: pointer; }
  button:hover { background: #1d4ed8; }
  ul { list-style: none; padding: 0; }
  .entry { border-top: 1px solid #eee; padding: 12px 0; }
  .entry-message { margin: 0 0 4px; white-space: pre-wrap; }
  .entry-meta { margin: 0; font-size: 0.85em; color: #666; }
</style>
</head>
<body>
  <h1>Guestbook</h1>
  <p>Sign below — entries are kept in a database that survives a restart.</p>
  <form method="POST" action="/entries">
    <input type="text" name="name" placeholder="Your name" maxlength="80" required>
    <textarea name="message" placeholder="Leave a message" rows="3" maxlength="1000" required></textarea>
    <button type="submit">Sign the guestbook</button>
  </form>
  <ul>${entriesHtml || '<li>No entries yet. Be the first!</li>'}</ul>
</body>
</html>`);
});

app.post('/entries', async (req, res) => {
  const name = (req.body.name || '').trim().slice(0, 80);
  const message = (req.body.message || '').trim().slice(0, 1000);
  if (!name || !message) {
    return res.redirect('/');
  }
  try {
    await pool.query('INSERT INTO entries (name, message) VALUES ($1, $2)', [
      name,
      message,
    ]);
  } catch (err) {
    console.error(err);
  }
  res.redirect('/');
});

app.listen(port, '0.0.0.0', () => {
  console.log(`guestbook listening on ${port}`);
});

